/** Executable on the local integration host once Vue/Vitest dependencies exist.
 * Only fetch is mocked. No existing V4 business components are replaced.
 * JSON fixtures were generated by the actual Stage A reader from supplied originals.
 */
import { afterEach, describe, expect, it, vi } from 'vitest';
import { mount, flushPromises } from '@vue/test-utils';
import Panel from '../../apps/web/src/components/research/WechatResearchPanel.vue';
import listFixture from './fixtures/list.json';
import detailFixture from './fixtures/detail.json';

const clone = <T,>(x: T): T => JSON.parse(JSON.stringify(x));
const response = (value: unknown) => new Response(JSON.stringify(value), { headers: { 'content-type': 'application/json' } });
let wrapper: ReturnType<typeof mount> | undefined;
afterEach(() => { wrapper?.unmount(); wrapper = undefined; vi.unstubAllGlobals(); });

it('shows the real report-only missing/legacy states and exact report bytes as text', async () => {
  vi.stubGlobal('fetch', vi.fn(async (url: string) => response(url.includes('?') ? listFixture : detailFixture)));
  wrapper = mount(Panel, { props: { archiveDate: '20260917' } });
  await flushPromises();
  expect(wrapper.get('[data-testid=wechat-card]').text()).toContain('LEGACY_INPUT_UNVERIFIED');
  for (const missing of ['coverage.csv','mentions.csv','unmapped.csv','summary.json']) expect(wrapper.text()).toContain(missing);
  expect(wrapper.text()).toContain('真实发布时间：未确认');
  await wrapper.get('[data-testid=wechat-open-report]').trigger('click'); await flushPromises();
  expect(wrapper.get('[data-testid=wechat-report]').text()).toContain('白毛研究报告');
  expect(wrapper.text()).toContain('未绑定；未借用新版材料');
});

it('keeps the embedded reading area vertical and collapses technical identity details', async () => {
  vi.stubGlobal('fetch', vi.fn(async (url: string) => response(url.includes('?') ? listFixture : detailFixture)));
  wrapper = mount(Panel, { props: { archiveDate: '20260917' } });
  await flushPromises();
  await wrapper.get('[data-testid=wechat-open-report]').trigger('click'); await flushPromises();
  expect(wrapper.get('.wechat-layout').classes()).toContain('wechat-layout--reading');
  expect(wrapper.find('.wechat-list').element.nextElementSibling?.classList.contains('wechat-detail')).toBe(true);
  const identity = wrapper.get('[data-testid=wechat-identity-details]');
  expect(identity.attributes('open')).toBeUndefined();
  expect(identity.get('summary').text()).toContain('身份与来源核验');
  expect(identity.text()).toContain(detailFixture.material.identity.package_id);
  expect(wrapper.get('[data-testid=wechat-report]').text()).toContain('白毛研究报告');
});

it('keeps hostile Markdown/HTML/links inert; no script, image or local file fetch', async () => {
  const d = clone(detailFixture);
  d.report.content = '<script>window.BAD=1</script>\n<img src="file:///etc/passwd" onerror="alert(1)">\n[x](javascript:alert(1))\n{{ 1+1 }}';
  const l = clone(listFixture); l.items[0].article.url = 'javascript:alert(1)';
  const fetch = vi.fn(async (url: string) => response(url.includes('?') ? l : d));
  vi.stubGlobal('fetch', fetch);
  wrapper = mount(Panel, { props: { archiveDate: '20260917' } }); await flushPromises();
  await wrapper.get('[data-testid=wechat-open-report]').trigger('click'); await flushPromises();
  expect(wrapper.find('script').exists()).toBe(false);
  expect(wrapper.find('img').exists()).toBe(false);
  expect(wrapper.find('iframe').exists()).toBe(false);
  expect(wrapper.find('a[href^="javascript:"]').exists()).toBe(false);
  expect(wrapper.get('[data-testid=wechat-report]').text()).toContain('<script>');
  expect(fetch).toHaveBeenCalledTimes(2);
});

it('clears old cards/report at reload and on network failure', async () => {
  const fetch = vi.fn(async () => response(listFixture)); vi.stubGlobal('fetch', fetch);
  wrapper = mount(Panel, { props: { archiveDate: '20260917' } }); await flushPromises();
  expect(wrapper.find('[data-testid=wechat-card]').exists()).toBe(true);
  fetch.mockRejectedValueOnce(new Error('network down'));
  await wrapper.get('form').trigger('submit'); await flushPromises();
  expect(wrapper.find('[data-testid=wechat-card]').exists()).toBe(false);
  expect(wrapper.find('[data-testid=wechat-report]').exists()).toBe(false);
  expect(wrapper.get('[data-testid=wechat-error]').text()).toContain('network down');
});

it('ignores a late response from a previously selected date', async () => {
  let finish: ((value: Response) => void) | undefined;
  const next = clone(listFixture); next.query.date = '20260920'; next.items[0].article.title = 'NEW DATE';
  vi.stubGlobal('fetch', vi.fn((url: string) => url.includes('date=20260917')
    ? new Promise<Response>(resolve => { finish = resolve; }) : Promise.resolve(response(next))));
  wrapper = mount(Panel, { props: { archiveDate: '20260917' } });
  await wrapper.setProps({ archiveDate: '20260920' }); await flushPromises();
  expect(wrapper.text()).toContain('NEW DATE');
  finish?.(response(listFixture)); await flushPromises();
  expect(wrapper.text()).toContain('NEW DATE');
  expect(wrapper.text()).not.toContain('风言风语信息更新 9.17');
});

it('rejects a detail payload for another record and displays no old report', async () => {
  const wrong = clone(detailFixture); wrong.material.record_id = 'f'.repeat(64);
  vi.stubGlobal('fetch', vi.fn(async (url: string) => response(url.includes('?') ? listFixture : wrong)));
  wrapper = mount(Panel, { props: { archiveDate: '20260917' } }); await flushPromises();
  await wrapper.get('[data-testid=wechat-open-report]').trigger('click'); await flushPromises();
  expect(wrapper.get('[data-testid=wechat-detail-error]').text()).toContain('版本不一致');
  expect(wrapper.find('[data-testid=wechat-report]').exists()).toBe(false);
});

it('paginates explicitly and does not cap all records at six/eight', async () => {
  const first = clone(listFixture); first.total = 21; first.next_cursor = 'test-cursor';
  const second = clone(listFixture); second.total = 21; second.items[0].record_id = 'e'.repeat(64); second.items[0].article.title = 'SECOND PAGE';
  vi.stubGlobal('fetch', vi.fn(async (url: string) => response(url.includes('cursor=') ? second : first)));
  wrapper = mount(Panel, { props: { archiveDate: '20260917' } }); await flushPromises();
  expect(wrapper.get('[data-testid=wechat-count]').text()).toContain('21');
  await wrapper.get('[data-testid=wechat-next]').trigger('click'); await flushPromises();
  expect(wrapper.text()).toContain('SECOND PAGE');
});

describe.each([
  ['NOT_CONFIGURED', 'wechat-unconfigured'], ['NOT_INDEXED', 'wechat-not-indexed'], ['READY', 'wechat-empty'],
])('%s', (status, selector) => {
  it('explains empty or unconfigured state without claiming integration success', async () => {
    const empty = { ...clone(listFixture), status, items: [], total: 0, returned: 0 };
    vi.stubGlobal('fetch', vi.fn(async () => response(empty)));
    wrapper = mount(Panel, { props: { archiveDate: '20260917' } }); await flushPromises();
    expect(wrapper.find(`[data-testid=${selector}]`).exists()).toBe(true);
  });
});
